// Local first-time Pro experience. No account, payment or AI requests.
const SETUP_KEY='cutrank_training_onboarding_v1';
const setupDefaults={step:0,complete:false,dismissed:false,answers:{goal:'',experience:'',days:'',equipment:'',weight:'',calories:'',protein:'',priorities:[],notes:''}};
let setup=structuredClone(setupDefaults);
try{const saved=JSON.parse(localStorage.getItem(SETUP_KEY)||'null');if(saved&&saved.answers)setup={...setup,...saved,answers:{...setup.answers,...saved.answers}};}catch{}
const setupQuestions=[
  {key:'goal',eyebrow:'YOUR DIRECTION',title:'What are you working towards?',description:'Choose the main goal you want your training to support.',options:[['gain','Build muscle','Build strength and muscle over time.','↗'],['lose','Lose fat','Work towards a leaner physique.','◈'],['maintain','Maintain','Keep a sustainable training routine.','◎']]},
  {key:'experience',eyebrow:'YOUR EXPERIENCE',title:'How long have you been training?',description:'A rough estimate helps us tailor the guidance to your experience.',options:[['under6m','Under 6 months','I’m new to strength training.','01'],['6m-2y','6 months–2 years','I’ve built some experience and consistency.','02'],['2-5y','2–5 years','I’ve trained for a few years.','03'],['over5y','5+ years','Training has been part of my life for a while.','04']]},
  {key:'days',eyebrow:'YOUR SCHEDULE',title:'What fits into your week?',description:'Choose a schedule you can realistically keep. You can change it later.',options:[['2','2 days','A simple, repeatable starting point.','2×'],['3','3 days','Room for training and recovery.','3×'],['4','4 days','A regular upper / lower routine.','4×'],['5','5 days','More days to spread your training across.','5×']]},
  {key:'equipment',eyebrow:'YOUR TRAINING SPACE',title:'What do you have access to?',description:'Your starting outline should fit the equipment you actually have.',options:[['gym','A full gym','Barbells, dumbbells, cables and machines.','▥'],['home','Dumbbells at home','A pair of dumbbells and space to move.','⌂'],['bodyweight','Body weight','Keep the starting outline equipment-free.','◇']]},
  {key:'basics',eyebrow:'YOUR STARTING NUMBERS',title:'A little context, if you have it.',description:'Already know your weight or daily targets? Add them here. Every field is optional.'},
  {key:'priorities',eyebrow:'YOUR PRIORITIES',title:'What matters most to you?',description:'Choose up to two priorities, or skip this for now.',options:[['strength','Stronger lifts'],['chest','Chest'],['back','Back'],['shoulders','Shoulders'],['legs','Legs'],['consistency','Consistency']]}
];
function saveSetup(){try{localStorage.setItem(SETUP_KEY,JSON.stringify(setup));}catch{toast('Setup is available for this visit. Browser storage is unavailable.');}}
function equipmentLabel(){return {gym:'Full gym',home:'Dumbbells at home',bodyweight:'Body weight'}[setup.answers.equipment]||'Not set';}
function planOutline(){const days=Number(setup.answers.days)||3;return days<=3?'Full body · '+days+' days per week':days===4?'Upper / lower · 4 days per week':'Upper / lower + focus day · 5 days per week';}
function syncSetupTrigger(){const button=$('#setupDemo');button.textContent=setup.complete?'Edit your setup ↗':setup.step>0?'Resume Pro setup ↗':'Try Pro onboarding ↗';}
function showSetup(step=setup.step){setup.step=Math.max(0,Math.min(7,step));setup.dismissed=false;saveSetup();$('#onboarding').hidden=false;$('main').inert=true;$('.sidebar').inert=true;document.body.classList.add('setup-open');renderSetup();}
function hideSetup(){saveSetup();$('#onboarding').hidden=true;$('main').inert=false;$('.sidebar').inert=false;document.body.classList.remove('setup-open');syncSetupTrigger();drawOverviewChart();renderProgress();$('#setupDemo').focus();}
function nextSetupStep(){const step=setup.reviewReturn?7:setup.step+1;setup.reviewReturn=false;showSetup(step);}
function choiceMarkup(question){if(question.key==='days')return daysMarkup();return `<fieldset class="setup-choices"><legend class="sr-only">${esc(question.title)}</legend>${question.options.map(([value,title,description,icon])=>`<label class="setup-choice"><input type="radio" name="${question.key}" value="${value}" ${setup.answers[question.key]===value?'checked':''}><span class="choice-icon" aria-hidden="true">${icon}</span><span><b>${title}</b><small>${description}</small></span><span class="choice-check" aria-hidden="true">✓</span></label>`).join('')}</fieldset>`;}
const sliderFields={weight:{label:'Body weight',min:35,max:180,step:.1,start:80,unit:'kg'},calories:{label:'Current calorie target',min:500,max:8000,step:1,start:2400,unit:'kcal'},protein:{label:'Current protein target',min:1,max:500,step:1,start:150,unit:'g'}};
function sliderFill(value,min,max){return Math.max(0,Math.min(100,(Number(value)-min)/(max-min)*100));}
function daysMarkup(){const days=setup.answers.days||'3';return `<div class="days-slider"><div class="days-figure"><output id="daysValue" for="setup-days">${esc(days)}</output><span>days per week</span></div><label class="sr-only" for="setup-days">Training days per week</label><input id="setup-days" class="setup-range" data-range="days" type="range" name="days" min="2" max="5" step="1" value="${esc(days)}" style="--slider-fill:${sliderFill(days,2,5)}%" aria-valuetext="${esc(days)} days per week"><div class="days-ticks">${[2,3,4,5].map(day=>`<button type="button" data-select-day="${day}" aria-label="Choose ${day} training days" class="${Number(days)===day?'selected':''}">${day}</button>`).join('')}</div><p id="daysCaption">${esc(setupQuestions[2].options.find(option=>option[0]===days)?.[2]||'Choose a schedule that fits your week.')}</p></div>`;}
function numberMarkup(){return `<div class="setup-sliders">${Object.entries(sliderFields).map(([key,cfg])=>{const value=setup.answers[key],position=value||cfg.start;return `<div class="slider-field ${value===''?'is-unset':''}" data-slider-field="${key}"><div class="slider-heading"><label for="setup-${key}">${cfg.label}</label><div class="slider-exact"><input type="number" data-exact="${key}" aria-label="Exact ${cfg.label.toLowerCase()}" min="${cfg.min}" max="${cfg.max}" step="${cfg.step}" value="${esc(value)}" placeholder="—"><span>${cfg.unit}</span><button type="button" data-clear-slider="${key}" aria-label="Clear ${cfg.label.toLowerCase()}" ${value===''?'hidden':''}>×</button></div></div><input id="setup-${key}" class="setup-range" data-range="${key}" type="range" name="${key}" min="${cfg.min}" max="${cfg.max}" step="${cfg.step}" value="${esc(position)}" style="--slider-fill:${sliderFill(position,cfg.min,cfg.max)}%" aria-valuetext="${value===''?'Not set; move slider to choose':esc(value+' '+cfg.unit)}"><div class="slider-scale"><span>${cfg.min} ${cfg.unit}</span><small>${value===''?'Optional · slide to set':'Selected · tap the number to fine-tune'}</small><span>${cfg.max.toLocaleString('en-GB')} ${cfg.unit}</span></div></div>`;}).join('')}</div><p class="setup-note">Leave any value unset if you don’t know it yet. These are your existing numbers; the demo does not calculate targets.</p>`;}
function updateSetupSlider(input){
  const key=input.dataset.range||input.dataset.exact,range=$('#setupForm [data-range="'+key+'"]');
  setup.answers[key]=input.value;
  if(key==='days'){$('#daysValue').textContent=input.value;range.setAttribute('aria-valuetext',input.value+' days per week');$('#daysCaption').textContent=setupQuestions[2].options.find(option=>option[0]===input.value)?.[2]||'';document.querySelectorAll('[data-select-day]').forEach(button=>button.classList.toggle('selected',button.dataset.selectDay===input.value));}
  else{
    const cfg=sliderFields[key],field=range.closest('.slider-field'),exact=field.querySelector('[data-exact]');
    if(input===range)exact.value=input.value;else if(input.value!==''&&input.validity.valid)range.value=input.value;
    field.classList.toggle('is-unset',input.value==='');field.querySelector('[data-clear-slider]').hidden=input.value==='';field.querySelector('.slider-scale small').textContent=input.value===''?'Optional · slide to set':'Selected · tap the number to fine-tune';range.setAttribute('aria-valuetext',input.value===''?'Not set; move slider to choose':input.value+' '+cfg.unit);
  }
  range.style.setProperty('--slider-fill',sliderFill(range.value,Number(range.min),Number(range.max))+'%');$('#setupError').textContent='';saveSetup();
}
function priorityMarkup(question){return `<fieldset class="setup-priorities"><legend class="sr-only">Your priorities</legend>${question.options.map(([value,title])=>`<label><input type="checkbox" name="priority" value="${value}" ${setup.answers.priorities.includes(value)?'checked':''}><span>${title}<b aria-hidden="true">＋</b></span></label>`).join('')}</fieldset><label class="setup-notes">Anything else you want your coach to know? <span>Optional</span><textarea name="notes" rows="3" maxlength="300" placeholder="Your preferences, available time, or anything you want to discuss…">${esc(setup.answers.notes)}</textarea></label><p class="setup-note">Your coach would review these notes before offering tailored suggestions.</p>`;}
function reviewMarkup(){const a=setup.answers;return `<div class="setup-review"><div class="plan-heading"><span>YOUR STARTING OUTLINE</span><h2>${esc(planOutline())}</h2><p>${esc(equipmentLabel())} · ${esc(goalNames[a.goal])}</p></div>${[['Main goal',goalNames[a.goal],1],['Experience',setupQuestions[1].options.find(option=>option[0]===a.experience)?.[1],2],['Training schedule',a.days+' days per week',3],['Equipment',equipmentLabel(),4],['Starting numbers',[a.weight?a.weight+' kg':null,a.calories?a.calories+' kcal':null,a.protein?a.protein+' g protein':null].filter(Boolean).join(' · ')||'Add later',5],['Priorities',a.priorities.map(key=>setupQuestions[5].options.find(option=>option[0]===key)?.[1]).join(', ')||'Explore as you go',6]].map(([label,value,step])=>`<div class="review-row"><span>${label}</span><b>${esc(value||'Not set')}</b><button type="button" data-edit-step="${step}" aria-label="Edit ${label.toLowerCase()}">Edit</button></div>`).join('')}${a.notes?'<div class="review-notes"><span>YOUR NOTES</span><p>'+esc(a.notes)+'</p></div>':''}</div><p class="setup-note">This is a preview of your setup. The workspace keeps its example training history; a connected coach and personalised routines come next.</p>`;}
function renderSetup(){
  const step=setup.step,welcome=step===0,review=step===7,q=setupQuestions[step-1];
  $('#onboarding').innerHTML=`<div class="setup-top"><a class="brand" href="#today"><img src="../../assets/cutrank-emblem.webp" alt="" width="38" height="38"><span>CUT<span>RANK</span><small>YOUR NEXT CHAPTER</small></span></a><span>LOCAL PROTOTYPE · EXAMPLE PRO ACCESS</span><button type="button" id="setupLater">${welcome?'Explore the example workspace':'Finish later'}</button></div><div class="setup-layout"><aside class="setup-intro"><span class="pro-pill">WELCOME TO CUTRANK PRO</span><h2>A starting point.<br>Built around you.</h2><p>Your goals, your schedule, your training. A few answers help bring it together.</p><div class="setup-path">${['Your goal','Your experience','Your schedule','Your equipment','Starting numbers','Your priorities'].map((label,i)=>`<div class="${step>i+1?'done':''} ${step===i+1?'current':''}"><span>${step>i+1?'✓':String(i+1).padStart(2,'0')}</span>${label}</div>`).join('')}</div><small>About a minute · editable any time</small></aside><div class="setup-main">${welcome?`<div class="setup-welcome-mark">✦</div><div class="eyebrow">LET’S MAKE IT YOURS</div><h1 id="onboardingTitle" tabindex="-1">You’re in.<br>Let’s find your starting point.</h1><p class="setup-description">Before your first session, tell us what you want to work towards. We’ll bring your answers together in a simple starting outline.</p><div class="welcome-benefits"><span>01 <b>A goal to work towards</b></span><span>02 <b>A schedule that fits your week</b></span><span>03 <b>Useful context for your coach</b></span></div><button id="beginSetup" class="primary full">Set up my workspace <span>↗</span></button><p class="setup-note">Demo only. Answers stay in this browser.</p>`:`<div class="setup-progress"><span>${review?'READY TO REVIEW':'QUESTION '+step+' OF 6'}</span><span>${review?'Your answers, brought together':Math.round((step-1)/6*100)+'% complete'}</span></div><div class="setup-progress-track"><span style="width:${review?100:(step-1)/6*100}%"></span></div><div class="eyebrow">${review?'YOUR STARTING POINT':q.eyebrow}</div><h1 id="onboardingTitle" tabindex="-1">${review?'Ready when you are.':q.title}</h1><p class="setup-description">${review?'Take a look through your answers. You can change any of them before you start.':q.description}</p><form id="setupForm">${review?reviewMarkup():step===5?numberMarkup():step===6?priorityMarkup(q):choiceMarkup(q)}<p class="setup-error" id="setupError" role="status"></p><div class="setup-actions"><button class="setup-back" type="button" id="setupBack">← Back</button><div>${!review&&step>=5?'<button class="setup-skip" id="setupSkip" type="button">Skip for now</button>':''}<button class="primary" type="submit">${review?'Open my workspace':'Continue'} <span>→</span></button></div></div></form>`}</div></div>`;
  $('#onboardingTitle').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});
  $('#setupLater').onclick=()=>{setup.dismissed=true;hideSetup();};
  if(welcome){$('#beginSetup').onclick=()=>showSetup(1);return;}
  $('#setupBack').onclick=()=>showSetup(step-1);
  if($('#setupSkip'))$('#setupSkip').onclick=()=>{if(step===5){setup.answers.weight='';setup.answers.calories='';setup.answers.protein='';}else{setup.answers.priorities=[];setup.answers.notes='';}nextSetupStep();};
  document.querySelectorAll('[data-edit-step]').forEach(button=>button.onclick=()=>{setup.reviewReturn=true;showSetup(Number(button.dataset.editStep));});
  $('#setupForm').onsubmit=event=>{event.preventDefault();if(review){completeSetup();return;}if(step===3&&!setup.answers.days)setup.answers.days=$('#setup-days').value;if(step<5&&!setup.answers[q.key]){$('#setupError').textContent='Choose an option to continue.';return;}nextSetupStep();};
  $('#setupForm').onchange=event=>{const input=event.target;if(input.type==='radio')setup.answers[input.name]=input.value;if(input.name==='priority'){const selected=[...$('#setupForm').querySelectorAll('[name="priority"]:checked')].map(element=>element.value);if(selected.length>2){input.checked=false;$('#setupError').textContent='Choose up to two priorities.';return;}setup.answers.priorities=selected;}$('#setupError').textContent='';saveSetup();};
  $('#setupForm').oninput=event=>{const input=event.target;if(input.hasAttribute('data-range')||input.hasAttribute('data-exact')){updateSetupSlider(input);return;}if(input.name==='notes'){setup.answers.notes=input.value;saveSetup();}};
  $('#setupForm').onclick=event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.selectDay){const range=$('#setup-days');range.value=button.dataset.selectDay;updateSetupSlider(range);}if(button.dataset.clearSlider){const key=button.dataset.clearSlider,exact=$('#setupForm [data-exact="'+key+'"]');exact.value='';updateSetupSlider(exact);}};
}
function completeSetup(){
  const a=setup.answers;if(!a.goal||!a.experience||!a.days||!a.equipment){showSetup(1);return;}
  setup.complete=true;setup.dismissed=false;state.onboardingProfile=structuredClone(a);state.goal=a.goal;
  if(a.calories)state.calorieTarget=Number(a.calories);if(a.protein)state.proteinTarget=Number(a.protein);
  if(a.weight)state.checkin={...(state.checkin||{}),date:TODAY,weight:Number(a.weight)};
  for(const message of state.messages)if(message.target)message.handled=true;
  persist();hideSetup();openTab('today');renderAll();toast('Your example workspace is ready. You can edit your setup any time.');
}
$('#setupDemo').onclick=()=>showSetup(setup.complete?7:setup.step);
$('#goal').addEventListener('change',()=>{if(!setup.complete)return;setup.answers.goal=state.goal;if(state.onboardingProfile)state.onboardingProfile.goal=state.goal;saveSetup();persist();});
$('#resetDemo').addEventListener('click',()=>{setup=structuredClone(setupDefaults);saveSetup();showSetup(0);});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#onboarding').hidden){setup.dismissed=true;hideSetup();}});
syncSetupTrigger();
if(!setup.complete&&!setup.dismissed)showSetup();
